import json
from fractions import Fraction as F
from math import isqrt

A = [[F(1), F(2)], [F(1), F(0)]]
forcing = [[F(0), F(0)], [F(-5), F(0)]]  # sin(t), cos(t)

def solve(matrix, rhs):
    n = len(rhs)
    m = [[F(v) for v in row] + [F(b)]
         for row, b in zip(matrix, rhs)]
    for col in range(n):
        pivot = next(r for r in range(col, n) if m[r][col])
        m[col], m[pivot] = m[pivot], m[col]
        divisor = m[col][col]
        m[col] = [v / divisor for v in m[col]]
        for r in range(n):
            if r != col:
                factor = m[r][col]
                m[r] = [u - factor * v
                        for u, v in zip(m[r], m[col])]
    return [row[-1] for row in m]

# Unknown coefficients are x_sin, x_cos, y_sin, y_cos.
# Differentiation maps (sin coefficient, cos coefficient) to (-cos, sin).
matrix, rhs = [], []
for i in range(2):
    for trig in range(2):
        row = [F(0)] * 4
        row[2 * i + (1 - trig)] += F(-1 if trig == 0 else 1)
        for j in range(2):
            row[2 * j + trig] -= A[i][j]
        matrix.append(row)
        rhs.append(forcing[i][trig])
particular = solve(matrix, rhs)

trace = A[0][0] + A[1][1]
det = A[0][0] * A[1][1] - A[0][1] * A[1][0]
disc = trace * trace - 4 * det

if disc.denominator != 1 or disc < 0:
    print("UNSUPPORTED")
else:
    root = isqrt(disc.numerator)
    if root * root != disc:
        print("UNSUPPORTED")
    else:
        eigenvalues = [(trace + root) / 2, (trace - root) / 2]
        vectors = [[F(1), (lam - A[0][0]) / A[0][1]]
                   for lam in eigenvalues]

        homogeneous_residual = [
            [lam * v[i] - sum(A[i][j] * v[j] for j in range(2))
             for i in range(2)]
            for lam, v in zip(eigenvalues, vectors)
        ]
        particular_residual = [
            sum(row[j] * particular[j] for j in range(4)) - b
            for row, b in zip(matrix, rhs)
        ]
        independent = (
            vectors[0][0] * vectors[1][1]
            - vectors[1][0] * vectors[0][1]
        )

        def expression(terms):
            result = ""
            for coefficient, symbol in terms:
                if not coefficient:
                    continue
                magnitude = abs(coefficient)
                term = ("" if magnitude == 1 else str(magnitude) + "*") + symbol
                if not result:
                    result = ("-" if coefficient < 0 else "") + term
                else:
                    result += (" - " if coefficient < 0 else " + ") + term
            return result or "0"

        if (not independent
                or any(any(row) for row in homogeneous_residual)
                or any(particular_residual)):
            print("UNSUPPORTED")
        else:
            solutions = []
            for i, name in enumerate(("x", "y")):
                terms = [
                    (v[i], "C%d*exp(%s*t)" % (k + 1, lam))
                    for k, (lam, v) in enumerate(zip(eigenvalues, vectors))
                ]
                terms += [
                    (particular[2 * i], "sin(t)"),
                    (particular[2 * i + 1], "cos(t)")
                ]
                solutions.append(name + "(t) = " + expression(terms))

            print(json.dumps({
                "final_answer": "; ".join(solutions)
                    + ", where C1 and C2 are arbitrary real constants, for all real t.",
                "evidence": {
                    "characteristic_polynomial": [
                        "1", str(-trace), str(det)
                    ],
                    "eigenvalues": list(map(str, eigenvalues)),
                    "particular_coefficients_xsin_xcos_ysin_ycos":
                        list(map(str, particular)),
                    "verified_residuals": "all zero",
                    "eigenvector_determinant": str(independent)
                }
            }, separators=(",", ":")))
